DROP POLICY IF EXISTS "bc_storage_select" ON storage.objects;
CREATE POLICY "bc_storage_select" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'business-cases' AND ((select auth.uid())::text = (storage.foldername(name))[1] OR owner_id = (select auth.uid())::text OR public.has_role((select auth.uid()),'admin') OR public.has_role((select auth.uid()),'pmo') OR public.has_role((select auth.uid()),'super_admin')));
DROP POLICY IF EXISTS "entregas_select_authenticated" ON storage.objects;
CREATE POLICY "entregas_select_authenticated" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'entregas' AND ((select auth.uid())::text = (storage.foldername(name))[1] OR owner_id = (select auth.uid())::text OR public.has_role((select auth.uid()),'admin') OR public.has_role((select auth.uid()),'pmo') OR public.has_role((select auth.uid()),'super_admin')));
DROP POLICY IF EXISTS "estrategia_insights_select_auth" ON storage.objects;
CREATE POLICY "estrategia_insights_select_auth" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'estrategia-insights' AND ((select auth.uid())::text = (storage.foldername(name))[1] OR owner_id = (select auth.uid())::text OR public.has_role((select auth.uid()),'admin') OR public.has_role((select auth.uid()),'pmo') OR public.has_role((select auth.uid()),'super_admin')));
DROP POLICY IF EXISTS "base sub leitura" ON storage.objects;
CREATE POLICY "base sub leitura" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'base-submissoes' AND ((select auth.uid())::text = (storage.foldername(name))[1] OR owner_id = (select auth.uid())::text OR public.has_role((select auth.uid()),'admin') OR public.has_role((select auth.uid()),'pmo') OR public.has_role((select auth.uid()),'super_admin')));
DROP POLICY IF EXISTS "backlog_sub_read_auth" ON storage.objects;
CREATE POLICY "backlog_sub_read_auth" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'backlog-submissoes' AND ((select auth.uid())::text = (storage.foldername(name))[1] OR owner_id = (select auth.uid())::text OR public.has_role((select auth.uid()),'admin') OR public.has_role((select auth.uid()),'pmo') OR public.has_role((select auth.uid()),'super_admin')));
DROP POLICY IF EXISTS "rdb_select_auth" ON storage.objects;
CREATE POLICY "rdb_select_auth" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'repositorio-docs' AND (owner_id = (select auth.uid())::text OR public.has_role((select auth.uid()),'admin') OR public.has_role((select auth.uid()),'pmo') OR public.has_role((select auth.uid()),'super_admin') OR (NOT public.is_lider_restrito((select auth.uid())) AND EXISTS (SELECT 1 FROM public.repositorio_documentos d WHERE d.arquivo_path = objects.name))));
DROP POLICY IF EXISTS "fluxos_auth_read" ON storage.objects;
CREATE POLICY "fluxos_auth_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'processo-fluxos' AND (owner_id = (select auth.uid())::text OR NOT public.is_lider_restrito((select auth.uid()))));